def count_hydrogen_atoms(molecular_formula):
    """
    Counts the number of hydrogen atoms in a molecular formula.

    Args:
        molecular_formula: A string representing the molecular formula

    Returns:
        The number of hydrogen atoms in the formula
    """
    # Find the position of 'H' in the formula
    if 'H' not in molecular_formula:
        return 0

    h_index = molecular_formula.find('H')

    # Extract the number following 'H'
    num_str = ""
    for i in range(h_index + 1, len(molecular_formula)):
        if molecular_formula[i].isdigit():
            num_str += molecular_formula[i]
        else:
            break

    # If there's no number after 'H', it means there's 1 hydrogen atom
    if num_str == "":
        return 1
    else:
        return int(num_str)

