def calculate_element_contributions(atom_counts, atomic_weights):
    """
    Calculate the weight contribution of each element to the molecular weight.

    Args:
        atom_counts: A dictionary with elements as keys and their counts as values
        atomic_weights: A dictionary with elements as keys and their atomic weights as values

    Returns:
        A dictionary with elements as keys and their total weight contributions as values
    """
    contributions = {}

    for element, count in atom_counts.items():
        if element in atomic_weights:
            contributions[element] = count * atomic_weights[element]
        else:
            raise ValueError(f"Atomic weight for {element} not found")

    return contributions

