def determine_dissociation(compound):
    """
    Determine the dissociation equation of a compound in water and identify the ions produced.

    Args:
        compound (str): Chemical formula of the compound

    Returns:
        dict: Dictionary containing the dissociation equation and ions produced
    """
    if compound == "Ca(NO3)2":
        equation = "Ca(NO3)2 → Ca²⁺ + 2NO₃⁻"
        ions = {"Ca2+": 1, "NO3-": 2}
        return {"equation": equation, "ions": ions}
    else:
        return {"equation": "Unknown compound", "ions": {}}

