def determine_sig_digits_density(mass, volume):
    """
    根据质量和体积的有效数字确定密度的有效数字。

    输入:
    mass: str或float，质量测量值
    volume: str或float，体积测量值

    输出:
    sig_digits: int，密度的有效数字位数
    """
    import re

    def count_sig_digits(value):
        s = str(value).strip()
        if 'e' in s or 'E' in s:
            s = format(float(s), 'f')
        s = s.lstrip('0')
        if '.' in s:
            s = s.replace('.', '')
            s = s.lstrip('0')
            return len(s)
        else:
            s = s.rstrip('0')
            return len(s)

    sig_mass = count_sig_digits(mass)
    sig_volume = count_sig_digits(volume)

    return min(sig_mass, sig_volume)

