def multiply_nc_by_t_power_3_2(N_c, t_power_3_2):
    """
    计算 N_c * T^{3/2}。

    输入:
    N_c: float, 导带有效态密度，单位 cm^{-3} K^{-3/2}
    t_power_3_2: float, 温度的3/2次方，单位 K^{3/2}

    输出:
    float, 乘积，单位 cm^{-3}
    """
    return N_c * t_power_3_2
